select nvl(IS_SPPI_PASS,sppi_test_status) IS_SPPI_PASS
from  fin_product   fp
left join SPPI_IMPORT_DATA sid on fp.finprod_id = sid.BOND_ID
where  fp.finprod_Market_id = #{finprodId}

	and fp.FINPROD_TYPE2 = #{finprodType2}

select distinct PLEDGE_STOCK_ID
from  PTL_SEC_STOCK
where PLEDGE_STOCK_NAME = #{zyqkName}
